import os
import re
from urllib.parse import urlparse, unquote
from pathlib import PurePosixPath
from flask import Flask, request, jsonify, send_file
import hashlib
import hmac

app = Flask(__name__)
app.config['UPLOAD_DIR'] = '/var/app/uploads'
app.config['SECRET_KEY'] = os.environ.get('APP_SECRET', 'default-dev-key-change-me')

def generate_token(username):
    return hmac.new(app.config['SECRET_KEY'].encode(), username.encode(), hashlib.sha256).hexdigest()

def verify_token(username, token):
    expected = generate_token(username)
    return hmac.compare_digest(expected, token)

class PathValidator:
    """Validates file paths to prevent directory traversal."""

    BLOCKED_SEQUENCES = ['../', '..\\', '%2e%2e', '%2E%2E']
    ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.doc', '.csv'}

    def __init__(self, base_dir):
        self.base_dir = os.path.realpath(base_dir)

    def _normalize_path(self, user_path):
        """Normalize the path by decoding and resolving."""
        # First pass: URL decode
        decoded = unquote(user_path)
        # Second pass: decode again to catch double-encoding
        decoded = unquote(decoded)
        return decoded

    def _check_blocked_sequences(self, path):
        """Check for blocked traversal sequences."""
        lower_path = path.lower()
        for seq in self.BLOCKED_SEQUENCES:
            if seq in lower_path:
                return False
        return True

    def _check_extension(self, path):
        """Verify file has an allowed extension."""
        _, ext = os.path.splitext(path)
        return ext.lower() in self.ALLOWED_EXTENSIONS

    def _resolve_and_check_prefix(self, full_path):
        """Resolve the full path and verify it's under base_dir."""
        resolved = os.path.normpath(full_path)
        return resolved.startswith(self.base_dir)

    def validate(self, user_path):
        """Full validation pipeline for user-supplied paths."""
        if not user_path or len(user_path) > 255:
            return None, "Invalid path length"

        # Normalize
        normalized = self._normalize_path(user_path)

        # Check for traversal sequences
        if not self._check_blocked_sequences(normalized):
            return None, "Blocked sequence detected"

        # Check extension
        if not self._check_extension(normalized):
            return None, "File type not allowed"

        # Build full path and verify prefix
        full_path = os.path.join(self.base_dir, normalized)
        if not self._resolve_and_check_prefix(full_path):
            return None, "Path escapes base directory"

        return full_path, None

validator = PathValidator(app.config['UPLOAD_DIR'])

@app.route('/api/files/<username>', methods=['GET'])
def get_file(username):
    token = request.headers.get('X-Auth-Token', '')
    if not verify_token(username, token):
        return jsonify({'error': 'Unauthorized'}), 401

    filepath = request.args.get('path', '')

    full_path, error = validator.validate(filepath)
    if error:
        return jsonify({'error': error}), 400

    if not os.path.isfile(full_path):
        return jsonify({'error': 'File not found'}), 404

    return send_file(full_path)

@app.route('/api/files/<username>/metadata', methods=['GET'])
def get_metadata(username):
    token = request.headers.get('X-Auth-Token', '')
    if not verify_token(username, token):
        return jsonify({'error': 'Unauthorized'}), 401

    filepath = request.args.get('path', '')

    full_path, error = validator.validate(filepath)
    if error:
        return jsonify({'error': error}), 400

    if not os.path.exists(full_path):
        return jsonify({'error': 'File not found'}), 404

    stat = os.stat(full_path)
    return jsonify({
        'size': stat.st_size,
        'modified': stat.st_mtime,
        'path': filepath
    })

if __name__ == '__main__':
    os.makedirs(app.config['UPLOAD_DIR'], exist_ok=True)
    app.run(host='127.0.0.1', port=8080)
